// TrustLoop upgrade: applications (hirer chooses) + outside work with authenticity checks.
// Run from the project root:  node apply-apps.mjs
// Backs up every file it replaces into .backup-apps/ first.
import fs from "node:fs";
import path from "node:path";

const FILES = {"src/app/actions/applications.ts":"","src/app/actions/external.ts":"","src/app/actions/work.ts":"","src/app/attest/[token]/page.tsx":"","src/app/dashboard/page.tsx":"","src/app/outside-work/page.tsx":"","src/app/p/[id]/page.tsx":"","src/app/tasks/[id]/page.tsx":"","src/components/AppNav.tsx":"","src/components/CopyLink.tsx":"","src/components/ExternalWorkForm.tsx":"","src/components/TrustBadges.tsx":"","src/lib/authenticity.ts":"","src/lib/trust.ts":""};

const MODELS = `
enum ApplicationStatus {
  PENDING
  ACCEPTED
  DECLINED
  WITHDRAWN
}

model Application {
  id            String            @id @default(cuid())
  task          Task              @relation(fields: [taskId], references: [id])
  taskId        String
  contributor   User              @relation(fields: [contributorId], references: [id])
  contributorId String
  note          String?
  status        ApplicationStatus @default(PENDING)
  createdAt     DateTime          @default(now())

  @@unique([taskId, contributorId])
  @@index([taskId])
}

model ExternalWork {
  id             String    @id @default(cuid())
  user           User      @relation(fields: [userId], references: [id])
  userId         String
  title          String
  description    String
  evidenceUrl    String
  clientName     String?
  refereeToken   String    @unique
  refereeName    String?
  refereeEmail   String?
  refereeComment String?
  refereeResponse String?
  respondedAt    DateTime?
  check          Json?
  checkedAt      DateTime?
  createdAt      DateTime  @default(now())

  @@index([userId])
  @@index([evidenceUrl])
}
`;

const root = process.cwd();
const schemaPath = path.join(root, "prisma", "schema.prisma");
if (!fs.existsSync(schemaPath) || !fs.existsSync(path.join(root, "src"))) {
  console.error("Run this from the project root (the folder with prisma/ and src/).");
  process.exit(1);
}

function addToModel(s, model, lines, nl) {
  const start = s.indexOf("model " + model + " {");
  if (start < 0) throw new Error("model " + model + " not found");
  let end = s.indexOf("\n}", start);
  if (end < 0) throw new Error("end of model " + model + " not found");
  if (s[end - 1] === "\r") end -= 1;
  return s.slice(0, end) + nl + lines.map((l) => "  " + l).join(nl) + s.slice(end);
}

// 1. Database schema
let s = fs.readFileSync(schemaPath, "utf8");
if (!s.includes("model LedgerEntry")) {
  console.error("Install the wallet upgrade first (node apply-wallet.mjs). Nothing was changed.");
  process.exit(1);
}
if (s.includes("model Application")) {
  console.log("schema.prisma already has these models, skipping.");
} else {
  const nl = s.includes("\r\n") ? "\r\n" : "\n";
  fs.mkdirSync(path.join(root, ".backup-apps", "prisma"), { recursive: true });
  fs.writeFileSync(path.join(root, ".backup-apps", "prisma", "schema.prisma"), s);
  s = addToModel(s, "User", ["applications  Application[]", "externalWorks ExternalWork[]"], nl);
  s = addToModel(s, "Task", ["applications Application[]"], nl);
  s = s.trimEnd() + nl + MODELS.replace(/\n/g, nl);
  fs.writeFileSync(schemaPath, s);
  console.log("Updated prisma/schema.prisma");
}

// 2. Source files
for (const [rel, b64] of Object.entries(FILES)) {
  const dest = path.join(root, rel);
  if (fs.existsSync(dest)) {
    const bk = path.join(root, ".backup-apps", rel);
    fs.mkdirSync(path.dirname(bk), { recursive: true });
    fs.copyFileSync(dest, bk);
  }
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.writeFileSync(dest, Buffer.from(b64, "base64"));
  console.log("Wrote " + rel);
}

// 3. Keep the backups out of git
const gi = path.join(root, ".gitignore");
if (fs.existsSync(gi) && !fs.readFileSync(gi, "utf8").includes(".backup-apps")) {
  fs.appendFileSync(gi, "\n.backup-apps/\n");
}

console.log(`
Done. Next, run these one at a time:
  1.  npx prisma migrate dev --name applications_outside_work
  2.  npm run build
`);
